'use strict';
(function(){
const C=MaisonCasting,esc=I.esc,screen=$('#startScreen');let draft=null,chosen=0,trioIndex=0;
let settings={sound:true,reducedMotion:false};try{Object.assign(settings,JSON.parse(localStorage.getItem('maison-settings')||'{}'));}catch(e){}
function applySettings(){document.body.classList.toggle('reduce-motion',settings.reducedMotion);}applySettings();
function heading(k,title,text){return `<span class="eyebrow">${k}</span><h1>${title}<span class="dot">.</span></h1><p class="start-intro">${text}</p>`;}
function shell(html){screen.innerHTML=`<div class="start-grain"></div><div class="start-inner"><div class="start-brand">⌂ <span>LA MAISON DES ACCORDS</span> ♪</div>${html}</div>`;screen.hidden=false;document.body.classList.add('at-home');document.querySelector('main').inert=true;document.querySelector('header').inert=true;window.homeOpen=true;setRunning(false);screen.querySelector('button')?.focus();}
function home(){shell(`<div class="home-art" aria-hidden="true"><span>🎸</span><span class="home-roof">⌂</span><span>🎹</span><i>♪</i><b>♫</b></div>${heading('UNE MAISON · DES PERSONNALITÉS · VOTRE MUSIQUE','Tout commence<br>sous le même toit','Trois musiciens. Trois chances. Quatre actes pour faire connaître ton groupe au monde entier.')}<nav class="home-menu" aria-label="Menu principal"><button id="continueGame" class="primary" ${saved?'':'disabled'}>Continuer <span>→</span></button><button id="createGame">Nouvelle partie <span>＋</span></button><button id="settingsGame">Paramètres <span>⚙</span></button><button id="wikiGame">Wiki <span>▤</span></button></nav><p class="tiny">${saved?'Ta maison t’attend · semaine '+W.week(state):'Choisis ton trio pour ouvrir les portes de la maison.'}</p>`);$('#continueGame').onclick=()=>enter(true);$('#createGame').onclick=chooseTrio;$('#settingsGame').onclick=()=>page('settings');$('#wikiGame').onclick=()=>page('wiki');}
function chooseTrio(){shell(`${heading('NOUVELLE PARTIE · 01 / 02','Choisis ton premier trio','Chaque instrument apporte sa couleur. La maison pourra accueillir jusqu’à six musiciens.')}<div class="trio-grid">${C.trios.map((t,i)=>`<button class="trio-card" data-trio="${i}"><span class="trio-instruments">${t.instruments.map(v=>`<span><b>${I.icons[v]}</b><small>${v}</small></span>`).join('')}</span><strong>${t.name}</strong><p>${t.note}</p><span class="trio-arrow">Créer ce collectif ↗</span></button>`).join('')}</div><button id="backHome" class="quiet">← Accueil</button>${saved?'<p class="tiny">La sauvegarde actuelle sera remplacée seulement à la confirmation finale.</p>':''}`);screen.querySelectorAll('[data-trio]').forEach(b=>b.onclick=()=>{trioIndex=Number(b.dataset.trio);draft=C.draft(trioIndex);chosen=0;choosePerson();});$('#backHome').onclick=home;}
function choosePerson(){const p=draft[chosen];shell(`${heading('NOUVELLE PARTIE · 02 / 02','Ton musicien dans la maison','Choisis ton instrument, puis un profil qui te plaît. Chaque membre gardera son autonomie.')}<div class="instrument-choices">${draft.map((p,i)=>`<button class="${i===chosen?'active':''}" aria-pressed="${i===chosen}" data-player="${i}">${I.icons[p.instrument]} ${p.instrument}</button>`).join('')}</div><div class="casting-profile">${I.portrait(p)}<div><span class="eyebrow">TON PERSONNAGE · ${I.icons[p.instrument]} ${p.instrument.toUpperCase()}</span><h2>${esc(p.name)}</h2><p>${esc(p.style)} · ${esc(p.want)}</p><div class="casting-tags">${p.traits.map(t=>`<span class="tag" title="${esc(S.TRAITS[t])}">${t}</span>`).join('')}</div><button id="rerollPlayer">⟳ Autre profil & apparence</button></div></div><div class="casting-peers"><span>LES DEUX AUTRES MEMBRES</span>${draft.filter((_,i)=>i!==chosen).map(I.person).join('')}</div><div class="start-actions"><button id="backTrio" class="quiet">← Changer de trio</button><button id="confirmGame" class="primary">${saved?'Remplacer la partie et commencer':'Ouvrir la maison'} →</button></div>`);screen.querySelectorAll('[data-player]').forEach(b=>b.onclick=()=>{chosen=Number(b.dataset.player);choosePerson();});$('#rerollPlayer').onclick=()=>{draft[chosen]=C.profile(p.id,p.instrument,Math.random,draft.map(p=>p.name));choosePerson();};$('#backTrio').onclick=chooseTrio;$('#confirmGame').onclick=()=>{state=C.create(draft,chosen);selected=state.playerId;positions={};$('#characters').innerHTML='';accumulator=0;speed=1;saved=true;document.querySelectorAll('.speed').forEach(b=>b.classList.toggle('active',b.dataset.speed==='1'));for(const ui of [window.MaisonMusicUI,window.MaisonWeeksUI,window.MaisonRailUI,window.MaisonTourUI])ui?.resetView();window.MaisonGuidanceUI?.reset();save();enter(true);};}
function enter(run){screen.hidden=true;window.homeOpen=false;document.body.classList.remove('at-home');document.querySelector('main').inert=false;document.querySelector('header').inert=false;render();setRunning(run);if(!window.MaisonTourUI?.maybeShow()&&!window.MaisonWeeksUI?.maybeShow())window.MaisonDecisionsUI?.maybeShow();$('#pause').focus();}
function page(type){if(type==='settings'){shell(`${heading('À TON RYTHME','Paramètres','Ces préférences restent sur cet appareil.')}<div class="settings-box"><label><span><strong>Sons des objectifs</strong><small>Un carillon discret à chaque étape accomplie.</small></span><input id="soundSetting" type="checkbox" ${settings.sound?'checked':''}></label><label><span><strong>Réduire les animations</strong><small>Atténuer les mouvements décoratifs et les effets des boutons.</small></span><input id="motionSetting" type="checkbox" ${settings.reducedMotion?'checked':''}></label></div><button id="backHome" class="quiet">← Accueil</button>`);for(const id of ['soundSetting','motionSetting'])$('#'+id).onchange=()=>{settings.sound=$('#soundSetting').checked;settings.reducedMotion=$('#motionSetting').checked;applySettings();localStorage.setItem('maison-settings',JSON.stringify(settings));};}else shell(`${heading('LE CARNET DE LA MAISON','Wiki','Les règles essentielles, à retrouver à tout moment.')}<div class="wiki-grid"><article><h2>☀ Le temps</h2><p>Une journée représente une semaine. Événements à 10 h, 17 h et minuit. Après le choix de minuit, les dormeurs rejoignent leur chambre. La nuit accélère automatiquement jusqu’au bilan de 8 h, puis chacun commence sa journée.</p></article><article><h2>♫ Les chansons</h2><p>À 80 %, propose un essai. Plus de la moitié du groupe doit accepter de participer. Sinon, repropose plus tard, sans vote ni réécriture. Après l’essai, un vote distinct décide de l’adoption à la majorité. Termine ensuite l’écriture et prépare-la à 100 %.</p><p>Qualité 1 à 7 = tours + énergie − 4. Limites : 3–6 tours et 2–5 énergie par tour. Le style favorise durée, énergie ou équilibre.</p></article><article><h2>↪ Une seconde chance</h2><p>Après le premier refus, une seule réécriture : +0 à +2 niveaux. Tours et énergie peuvent monter ou descendre. Le résultat comparé apparaît même sans gain. Les auteurs peuvent décliner la proposition et décider de la reprendre plus tard. Scrapper supprime définitivement la chanson, sans archive ni nouvel essai. Deuxième refus sans abandon : archive personnelle, droits conservés. Après adoption, qualité verrouillée.</p></article><article><h2>✎ Les compositeurs</h2><p>Une contribution à une chanson terminée compte une seule fois. Débutant : niveaux 1–2. Après 3 chansons : En progrès, 2–3. Après 7 : Confirmé, 3–5. Après 12 : Accompli, 4–6, rarement 7. Les réécritures ne donnent pas de crédit supplémentaire.</p></article><article><h2>♡ Les personnalités</h2><p>Tags, énergie, moral et relations orientent leurs choix. Un refus reste visible dans leur fiche et près de leur portrait. Double-clique sur un musicien pour tout voir.</p><p>Vie du groupe propose parfois un choix facultatif : apaiser une tension, partager une idée ou respecter un besoin de calme. Les effets sont annoncés avant de répondre. Tu peux reporter ou laisser passer sans malus; les souvenirs restent consultables.</p></article><article><h2>★ Le premier show</h2><p>Deux shows ordinaires espacés de huit semaines, puis la finale d’acte la semaine suivante. Quatre actes : local, national, international et mondial. La résistance du public augmente à chaque acte : fais évoluer tes chansons et tes cartes. Les contrats déjà choisis conservent leurs conditions. Départ ensemble à 11 h, retour à 22 h. Le calendrier annonce un à trois styles probables du public, avec une part d’inconnu. La barre de la maison affiche les trois dates et le temps restant. Clique sur le nom de la scène pour choisir la destination et sa récompense. Le panneau suit les chansons et les styles encore à préparer, avec accès aux fiches. Un répertoire prêt ne remplace pas les objectifs à réussir sur scène. À zéro chance, la partie est perdue. Une finale d’acte réussie ouvre le suivant et rend une chance (maximum 3). La finale mondiale remporte la partie. Rencontres, cartes, masterclasses et résidences d’écriture sont annoncées avant de choisir le show. Une rencontre gagnée permet un essai d’une semaine avant le vote du groupe et l’accord de l’invité. BandLive : choisis jusqu’à deux passages, joue tes cartes pour conquérir le public. Énergie de carte renouvelée selon la chanson. Fatigue : −2 par carte pour son auteur et −1 par musicien en fin de tour. À 31–60 énergie personnelle : −2 puissance; à 0–30 : −3. Cette fatigue reste au retour.</p></article></div><button id="backHome" class="quiet">← Accueil</button>`);$('#backHome').onclick=home;}
function open(){if($('#dialog').open){dialogWasRunning=false;window.homeOpen=true;closeDialog();}home();}
window.MaisonStartUI={home:open,newGame:()=>{open();chooseTrio();},settings,enter};$('#homeButton').onclick=open;home();
})();
